import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.Bbwa0s72.js";const p=JSON.parse('{"title":"WorkerEndpoint — takoform_worker_endpoint","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/edge/worker-endpoint.md","filePath":"proposals/edge/worker-endpoint.md"}'),n={name:"proposals/edge/worker-endpoint.md"};function s(i,e,d,h,c,l){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="workerendpoint-—-takoform-worker-endpoint" tabindex="-1">WorkerEndpoint — <code>takoform_worker_endpoint</code> <a class="header-anchor" href="#workerendpoint-—-takoform-worker-endpoint" aria-label="Permalink to &quot;WorkerEndpoint — `takoform_worker_endpoint`&quot;">​</a></h1><h2 id="workload-and-consumer" tabindex="-1">Workload and consumer <a class="header-anchor" href="#workload-and-consumer" aria-label="Permalink to &quot;Workload and consumer&quot;">​</a></h2><p>A team wants their worker reachable, now, and does not yet own a domain — or owns one and does not want the first request to wait on delegation and verification. External clients reach the worker&#39;s active deployment over HTTPS at an address the host assigns and publishes; TLS termination and the naming scheme are the host&#39;s obligation, never portable state.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><p><code>attachment</code>. Inward activation is an attachment resource, never a binding (decision 0010). Deleting the attachment removes the address and never deletes the worker.</p><h2 id="observable-semantics" tabindex="-1">Observable semantics <a class="header-anchor" href="#observable-semantics" aria-label="Permalink to &quot;Observable semantics&quot;">​</a></h2><p><code>worker</code> is the only desired member, and it is immutable: changing it replaces the attachment. Requests at the assigned address invoke the worker&#39;s <code>fetch</code> handler, resolved through its ACTIVE DEPLOYMENT, so promotion and rollback move what answers without the endpoint being re-applied and without the address changing.</p><p>The address is published as outputs: <code>hostname</code> is the assigned DNS name, and <code>url</code> is exactly <code>https://</code> + that hostname + <code>/</code>. A portable author may rely on a value being returned, on the scheme being HTTPS, and on the address routing to the active deployment. They may rely on nothing about its shape — which subdomain, which apex, how long the label is — and must not parse it, assert a suffix, or reconstruct it from the resource name.</p><p>A worker has at most one endpoint. A host that cannot assign an address refuses the attachment with <code>unsupported_capability</code> rather than answering with an address it did not assign.</p><h2 id="why-this-is-one-form" tabindex="-1">Why this is one Form <a class="header-anchor" href="#why-this-is-one-form" aria-label="Permalink to &quot;Why this is one Form&quot;">​</a></h2><p>Reachability without a name of one&#39;s own is one complete observable fact: the worker answers at an address, over HTTPS, at the path root. Nothing about it is a variant of serving a customer-owned hostname — the desired states are disjoint, one carrying a hostname and the other carrying none — so merging the two would need a selector token between two different requests.</p><h2 id="what-would-require-a-separate-form" tabindex="-1">What would require a separate Form <a class="header-anchor" href="#what-would-require-a-separate-form" aria-label="Permalink to &quot;What would require a separate Form&quot;">​</a></h2><p>A name the author owns is <code>WorkerCustomDomain</code>. Path-pattern or zone-scoped routes carry matching semantics beyond a whole address and are a separate attachment Form (<code>WorkerRoute</code> in the family plan, <a href="./../../spec/form-families.html">spec/form-families.md</a>). An address with a chosen label, a reserved name, or a regional affinity would put host placement into desired state and is not a Form at all.</p><h2 id="provided-interfaces" tabindex="-1">Provided Interfaces <a class="header-anchor" href="#provided-interfaces" aria-label="Permalink to &quot;Provided Interfaces&quot;">​</a></h2><p>None.</p><h2 id="accepted-bindings" tabindex="-1">Accepted Bindings <a class="header-anchor" href="#accepted-bindings" aria-label="Permalink to &quot;Accepted Bindings&quot;">​</a></h2><p>None.</p><h2 id="lifecycle-risks" tabindex="-1">Lifecycle risks <a class="header-anchor" href="#lifecycle-risks" aria-label="Permalink to &quot;Lifecycle risks&quot;">​</a></h2><p>The assigned address must be stable for the life of one incarnation: a consumer holding the URL must not find it moved by a deployment change it did not make. A second endpoint against one worker must be refused deterministically, by the worker&#39;s UID rather than its name. Deleting the worker while the endpoint exists must fail with <code>dependency_in_use</code>. Import must recover the worker reference and the assigned address exactly, without minting a new one.</p><h2 id="prior-art" tabindex="-1">Prior art <a class="header-anchor" href="#prior-art" aria-label="Permalink to &quot;Prior art&quot;">​</a></h2><p>The vendor-subdomain endpoint of a proven edge platform, with the subdomain scheme kept host-side and the address published as contract rather than inferred.</p>',21)])])}const u=a(n,[["render",s]]);export{p as __pageData,u as default};
